    expected[0] = &.{ 1, 2, 3, 4 };
    expected[1] = &.{ 12, 13, 14, 5 };
    expected[2] = &.{ 11, 16, 15, 6 };
    expected[3] = &.{ 10, 9, 8, 7 };
    try testing.checkAllAllocationFailures(
        testing.allocator,
        spiralTest,
        .{ 4, &expected },
    );
}

test "spiral of size 5" {
